bool Hook::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("name"))
    {
        if(!validJsonOfField(1, "name", pJson["name"], err, true))
            return false;
    }
    else
    {
        err="The name column cannot be null";
        return false;
    }
    if(pJson.isMember("display_name"))
    {
        if(!validJsonOfField(2, "display_name", pJson["display_name"], err, true))
            return false;
    }
    else
    {
        err="The display_name column cannot be null";
        return false;
    }
    if(pJson.isMember("is_active"))
    {
        if(!validJsonOfField(3, "is_active", pJson["is_active"], err, true))
            return false;
    }
    if(pJson.isMember("config"))
    {
        if(!validJsonOfField(4, "config", pJson["config"], err, true))
            return false;
    }
    if(pJson.isMember("events"))
    {
        if(!validJsonOfField(5, "events", pJson["events"], err, true))
            return false;
    }
    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(6, "created_at", pJson["created_at"], err, true))
            return false;
    }
    if(pJson.isMember("modified_at"))
    {
        if(!validJsonOfField(7, "modified_at", pJson["modified_at"], err, true))
            return false;
    }
    return true;
}
